function compute(s) {
  var n = Math.max(1, Math.min(6, Math.round(s.n)));
  var w = (s.w || []).slice(0, n);
  while (w.length < n) w.push(0);
  w = w.map(function (x) { return (typeof x === "number" && isFinite(x) && x > 0) ? x : 0; });

  var total = L.sum(w);
  var p = w.map(function (x) { return total > 0 ? x / total : 1 / n; });
  var contrib = p.map(function (pi) {
    if (pi <= 0) return 0;
    return -pi * L.log2(pi);
  });
  var H = L.sum(contrib);
  var Hmax = L.log2(n);
  var gap = Hmax - H;
  var maxContribIdx = L.argmax(contrib);
  return {
    n: n,
    w: w,
    p: p,
    contrib: contrib,
    H: H,
    Hmax: Hmax,
    gap: gap,
    uniform: 1 / n,
    maxContribIdx: maxContribIdx,
    maxContrib: contrib[maxContribIdx],
    sumP: L.sum(p),
    sumContrib: L.sum(contrib)
  };
}

function render(s, r) {
  var W = 760, Hh = 340;
  var body = "";
  var padL = 56, padR = 20, padT = 46, padB = 54;
  var gapX = 34;
  var panelW = (W - padL - padR - gapX) / 2;
  var panelH = Hh - padT - padB;
  var leftX = padL, rightX = padL + panelW + gapX;
  var topY = padT;

  body += L.text(W / 2, 22, "Probabilities p_i  \u2192  contributions -p_i log2 p_i  \u2192  total H", { size: 15, anchor: "middle", weight: "bold" });

  // ---- left panel: probabilities ----
  var n = r.n;
  var barW = panelW / n;
  var maxP = Math.max(1, L.max(r.p));
  var pScale = L.scale(0, maxP, topY + panelH, topY);
  body += L.text(leftX + panelW / 2, topY - 12, "Probabilities p_i", { size: 13, anchor: "middle", weight: "bold" });
  body += L.line(leftX, topY + panelH, leftX + panelW, topY + panelH, { color: "#333", width: 1.5 });
  body += L.line(leftX, topY, leftX, topY + panelH, { color: "#333", width: 1.5 });
  body += L.text(leftX - 8, topY, "1", { size: 12, anchor: "end", baseline: "middle" });
  body += L.text(leftX - 8, topY + panelH, "0", { size: 12, anchor: "end", baseline: "middle" });
  var yUni = pScale(r.uniform);
  body += L.line(leftX, yUni, leftX + panelW, yUni, { color: "#888", width: 1.2, dash: "5 4" });
  body += L.text(leftX + panelW - 2, yUni - 6, "1/n = " + L.fmt(r.uniform, 3), { size: 12, anchor: "end", color: "#666" });
  for (var i = 0; i < n; i++) {
    var bx = leftX + i * barW + barW * 0.15;
    var bw = barW * 0.7;
    var y0 = pScale(r.p[i]);
    var bh = (topY + panelH) - y0;
    if (bh < 0) bh = 0;
    body += L.rect(bx, y0, bw, bh, { fill: L.color(i), stroke: "#333", rx: 2, opacity: 0.85 });
    body += L.text(bx + bw / 2, topY + panelH + 16, "p" + (i + 1), { size: 12, anchor: "middle" });
    body += L.text(bx + bw / 2, y0 - 6, L.fmt(r.p[i], 3), { size: 12, anchor: "middle" });
  }

  // ---- right panel: contributions ----
  var maxC = Math.max(0.001, L.max(r.contrib), r.Hmax);
  var cScale = L.scale(0, maxC, topY + panelH, topY);
  body += L.text(rightX + panelW / 2, topY - 12, "Contributions -p_i log2 p_i (bits)", { size: 13, anchor: "middle", weight: "bold" });
  body += L.line(rightX, topY + panelH, rightX + panelW, topY + panelH, { color: "#333", width: 1.5 });
  body += L.line(rightX, topY, rightX, topY + panelH, { color: "#333", width: 1.5 });
  body += L.text(rightX - 8, topY, L.fmt(maxC, 2), { size: 12, anchor: "end", baseline: "middle" });
  body += L.text(rightX - 8, topY + panelH, "0", { size: 12, anchor: "end", baseline: "middle" });
  var yMax = cScale(r.Hmax);
  body += L.line(rightX, yMax, rightX + panelW, yMax, { color: "#c0392b", width: 1.4, dash: "6 4" });
  body += L.text(rightX + panelW - 2, yMax - 6, "log2 n = " + L.fmt(r.Hmax, 3), { size: 12, anchor: "end", color: "#c0392b" });
  var yH = cScale(r.H);
  body += L.line(rightX, yH, rightX + panelW, yH, { color: "#1a5276", width: 2 });
  body += L.text(rightX + 4, yH - 6, "H = " + L.fmt(r.H, 3) + " bits", { size: 12, anchor: "start", color: "#1a5276", weight: "bold" });
  if (s.showContrib) {
    var cbarW = panelW / n;
    for (var j = 0; j < n; j++) {
      var cx = rightX + j * cbarW + cbarW * 0.15;
      var cw = cbarW * 0.7;
      var cy0 = cScale(r.contrib[j]);
      var ch = (topY + panelH) - cy0;
      if (ch < 0) ch = 0;
      body += L.rect(cx, cy0, cw, ch, { fill: L.color(j), stroke: "#333", rx: 2, opacity: 0.85 });
      body += L.text(cx + cw / 2, topY + panelH + 16, "p" + (j + 1), { size: 12, anchor: "middle" });
      if (r.contrib[j] > 0.0005) {
        body += L.text(cx + cw / 2, cy0 - 6, L.fmt(r.contrib[j], 3), { size: 12, anchor: "middle" });
      }
    }
  } else {
    body += L.text(rightX + panelW / 2, topY + panelH / 2, "contribution bars hidden", { size: 13, anchor: "middle", color: "#888" });
  }

  body += L.text(W / 2, Hh - 12, "H = " + L.fmt(r.H, 3) + " bits    Hmax = log2(" + n + ") = " + L.fmt(r.Hmax, 3) + " bits    gap = " + L.fmt(r.gap, 3) + " bits", { size: 13, anchor: "middle", weight: "bold" });

  return L.svg(W, Hh, body);
}

function show(s, r) {
  var rows = [];
  rows.push({ label: "n (number of outcomes)", value: r.n, digits: 0, note: "sets the ceiling log2 n" });
  rows.push({ label: "sum of weights", value: L.sum(r.w), digits: 3, note: "normalizing constant" });
  rows.push({ label: "p_i (normalized)", value: r.p, digits: 3, colLabels: r.p.map(function (_, i) { return "p" + (i + 1); }), note: "p_i = w_i / sum_j w_j" });
  rows.push({ label: "sum p_i", value: r.sumP, digits: 6, note: "must equal 1" });
  rows.push({ label: "-p_i log2 p_i", value: r.contrib, digits: 3, colLabels: r.contrib.map(function (_, i) { return "p" + (i + 1); }), highlight: [r.maxContribIdx], note: "largest single contribution highlighted" });
  rows.push({ label: "H (entropy, bits)", value: r.H, digits: 3, note: "sum of the contributions" });
  rows.push({ label: "Hmax = log2 n", value: r.Hmax, digits: 3, note: "attained only when all p_i = 1/n" });
  rows.push({ label: "gap = Hmax - H", value: r.gap, digits: 3, note: "0 exactly when the distribution is uniform" });
  return rows;
}

function checks(s, r) {
  var out = [];
  var tol = 1e-9;

  out.push({
    name: "Probabilities sum to 1",
    pass: Math.abs(r.sumP - 1) < 1e-9,
    detail: "sum p_i = " + L.fmt(r.sumP, 6)
  });

  var inRange = r.p.every(function (pi) { return pi >= -tol && pi <= 1 + tol; });
  out.push({
    name: "Every p_i lies in [0, 1]",
    pass: inRange,
    detail: "min p_i = " + L.fmt(L.min(r.p), 6) + ", max p_i = " + L.fmt(L.max(r.p), 6)
  });

  out.push({
    name: "H is non-negative",
    pass: r.H >= -tol,
    detail: "H = " + L.fmt(r.H, 6) + " bits"
  });

  var zeroCase = r.p.every(function (pi) { return pi <= tol || Math.abs(pi - 1) < tol; });
  var hIsZero = Math.abs(r.H) < 1e-9;
  out.push({
    name: "H = 0 exactly when one outcome is certain",
    pass: (zeroCase === hIsZero),
    detail: "certain = " + zeroCase + ", H = " + L.fmt(r.H, 6)
  });

  var uniform = r.p.every(function (pi) { return Math.abs(pi - r.uniform) < 1e-9; });
  var atMax = Math.abs(r.H - r.Hmax) < 1e-9;
  out.push({
    name: "H = log2 n exactly when all p_i = 1/n",
    pass: (uniform === atMax),
    detail: "uniform = " + uniform + ", H = " + L.fmt(r.H, 6) + ", log2 n = " + L.fmt(r.Hmax, 6)
  });

  out.push({
    name: "H never exceeds log2 n",
    pass: r.H <= r.Hmax + 1e-9,
    detail: "H = " + L.fmt(r.H, 6) + " <= " + L.fmt(r.Hmax, 6)
  });

  out.push({
    name: "Contributions sum to H",
    pass: Math.abs(r.sumContrib - r.H) < 1e-9,
    detail: "sum contributions = " + L.fmt(r.sumContrib, 6) + ", H = " + L.fmt(r.H, 6)
  });

  var noNaN = r.p.every(function (pi) { return isFinite(pi); }) &&
    r.contrib.every(function (c) { return isFinite(c); }) &&
    isFinite(r.H) && isFinite(r.Hmax);
  out.push({
    name: "No NaN or Infinity in any computed value",
    pass: noNaN,
    detail: "all p_i, contributions, H and log2 n are finite"
  });

  return out;
}
